import ast

def parse_user_input(text):
    try:
        return ast.literal_eval(text)
    except (ValueError, SyntaxError, TypeError) as exc:
        raise ValueError('Input must be a valid Python literal') from exc

tests:
assert parse_user_input('[1, 2, 3]') == [1, 2, 3]
assert parse_user_input('{"a": 1}') == {'a': 1}
assert parse_user_input('42') == 42

